#!/usr/bin/env bash
# Adjusts the Android project generated by `tauri android init` (gen/android).
# Run from the repository root after init.
set -euo pipefail

MANIFEST=gen/android/app/src/main/AndroidManifest.xml
test -f "$MANIFEST" || { echo "Missing $MANIFEST"; exit 1; }

# Internet for map tiles / OpenStreetMap, and legacy storage so Android 9/10 can write
# worlds to Download/Arnis. Android 11+ allows creating files in Download without it.
add_permission() {
  grep -q "$1" "$MANIFEST" || sed -i "s#<application#$2\n    <application#" "$MANIFEST"
}
add_permission 'android.permission.INTERNET' '<uses-permission android:name="android.permission.INTERNET" />'
add_permission 'android.permission.WRITE_EXTERNAL_STORAGE' '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="29" />'
# Location for the "Mi ubicación" map button. The WebView (wry) asks for it at runtime
# the first time the page calls navigator.geolocation.
add_permission 'android.permission.ACCESS_COARSE_LOCATION' '<uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" />'
add_permission 'android.permission.ACCESS_FINE_LOCATION' '<uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" />'
grep -q 'android.hardware.location.gps' "$MANIFEST" || \
  sed -i 's#<application#<uses-feature android:name="android.hardware.location.gps" android:required="false" />\n    <application#' "$MANIFEST"
grep -q 'requestLegacyExternalStorage' "$MANIFEST" || \
  sed -i 's#<application#<application android:requestLegacyExternalStorage="true"#' "$MANIFEST"

# Nombre que se ve bajo el ícono: es una versión no oficial (como «Ventoy no oficial»)
STRINGS=gen/android/app/src/main/res/values/strings.xml
if [ -f "$STRINGS" ]; then
  sed -i 's#<string name="app_name">[^<]*</string>#<string name="app_name">Arnis no oficial</string>#' "$STRINGS"
  sed -i 's#<string name="main_activity_title">[^<]*</string>#<string name="main_activity_title">Arnis no oficial</string>#' "$STRINGS"
else
  # sin strings.xml: el nombre va directo en el manifiesto
  sed -i 's#android:label="[^"]*"#android:label="Arnis no oficial"#g' "$MANIFEST"
fi
grep -q 'Arnis no oficial' "$STRINGS" "$MANIFEST" 2>/dev/null && echo "Nombre: Arnis no oficial"

# Always dark, like the desktop app (the WebView follows the app theme's light/dark flag).
for themes in gen/android/app/src/main/res/values/themes.xml gen/android/app/src/main/res/values-night/themes.xml; do
  [ -f "$themes" ] || continue
  sed -i 's/\.DayNight//g; s/\.Light\././g; s/\.Light"/"/g' "$themes"
done

# MainActivity: no edge-to-edge (the app starts below the status bar instead of under
# the clock) and the WebView keeps its text at 100%, so a large system font size does
# not break the one-screen layout.
ACTIVITY=$(find gen/android/app/src/main/java -name MainActivity.kt | head -1)
if [ -n "$ACTIVITY" ]; then
  PKG=$(sed -n 's/^package \(.*\)$/\1/p' "$ACTIVITY" | head -1)
  cat > "$ACTIVITY" <<KOTLIN
package $PKG

import android.content.ComponentName
import android.content.pm.PackageManager
import android.os.Bundle
import android.view.View
import android.webkit.JavascriptInterface
import android.webkit.WebView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MainActivity : TauriActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    // Android 15+ always draws apps edge to edge: keep the app clear of the status
    // bar, the navigation bar and camera cutouts by padding the content view.
    val root = findViewById<View>(android.R.id.content)
    ViewCompat.setOnApplyWindowInsetsListener(root) { v, insets ->
      val bars = insets.getInsets(
        WindowInsetsCompat.Type.systemBars() or WindowInsetsCompat.Type.displayCutout()
      )
      v.setPadding(bars.left, bars.top, bars.right, bars.bottom)
      WindowInsetsCompat.CONSUMED
    }
  }

  override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    // Keep text at 100% so a large system font does not break the layout.
    webView.settings.textZoom = 100
    // Íconos de temporada: la página dice cuál quiere y se cambia al salir de la app
    // (cambiarlo con la app abierta puede cerrarla en algunos celulares).
    webView.addJavascriptInterface(object {
      @JavascriptInterface
      fun setIcon(name: String) {
        if (name in ICONS) pendingIcon = name
      }

      @JavascriptInterface
      fun current(): String = currentIcon()
    }, "ArnisIcons")
  }

  private var pendingIcon: String? = null

  private fun alias(name: String) = ComponentName(packageName, "$PKG.\$name")

  private fun currentIcon(): String {
    for (a in ICONS) {
      val s = packageManager.getComponentEnabledSetting(alias(a))
      if (s == PackageManager.COMPONENT_ENABLED_STATE_ENABLED ||
        (s == PackageManager.COMPONENT_ENABLED_STATE_DEFAULT && a == "Inicio")) return a
    }
    return "Inicio"
  }

  override fun onStop() {
    super.onStop()
    val want = pendingIcon ?: return
    pendingIcon = null
    if (want == currentIcon()) return
    try {
      packageManager.setComponentEnabledSetting(alias(want),
        PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
      for (a in ICONS) if (a != want) packageManager.setComponentEnabledSetting(alias(a),
        PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
    } catch (e: Exception) {
    }
  }

  companion object {
    private val ICONS = listOf("Inicio", "InicioNavidad", "InicioVelitas", "InicioValentin", "InicioAmistad")
  }
}
KOTLIN
  echo "--- MainActivity.kt ---"
  cat "$ACTIVITY"
fi

# Íconos de temporada: el ícono del inicio pasa a unos activity-alias (uno por temporada, solo
# uno prendido); MainActivity.kt los cambia cuando la página se lo pide (js/season.js).
RES=gen/android/app/src/main/res
cp -r android/icons/mipmap-* "$RES/"
BG='@color/ic_launcher_background'
grep -rqs 'name="ic_launcher_background"' "$RES/values" || BG='@android:color/white'
mkdir -p "$RES/mipmap-anydpi-v26"
for s in navidad velitas valentin amistad; do
  cat > "$RES/mipmap-anydpi-v26/ic_launcher_$s.xml" <<XML
<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="$BG" />
    <foreground android:drawable="@mipmap/ic_launcher_${s}_foreground" />
</adaptive-icon>
XML
done
python3 android/season-aliases.py "$MANIFEST"

echo "--- AndroidManifest.xml ---"
cat "$MANIFEST"
echo "--- themes ---"
cat gen/android/app/src/main/res/values/themes.xml 2>/dev/null || true
